-- 2FA enrollment and recovery codes (USR-DASH-04).

-- Secret generated by "start 2FA setup", moved to totp_secret_enc once the
-- user proves it works with a valid code.
ALTER TABLE logins ADD COLUMN totp_pending_enc BLOB;

-- One-time recovery codes, stored as SHA-256 (the codes are random, 50 bits+).
CREATE TABLE recovery_codes (
    login_id  TEXT NOT NULL REFERENCES logins (id) ON DELETE CASCADE,
    code_hash BLOB NOT NULL,
    used_at   TEXT,
    PRIMARY KEY (login_id, code_hash)
) STRICT;
